/**
 * Email Template Types — Sawaa Dashboard
 *
 * Every RESPONSE shape is derived from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. `test/unit/lib/comms-type-contract.spec.ts` pins that.
 *
 * `blocks` is the one documented deviation: the wire column is free-form JSON
 * (the database does not enforce the builder vocabulary), while the dashboard
 * only ever writes/renders the block union below. The type narrows the wire
 * value to that union; nothing is transformed at runtime.
 */

import type { components } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Builder vocabulary (local; the JSON column has no schema) ─── */

export type EmailBlock =
  | { type: "heading"; id: string; text: string; level: 1 | 2 | 3 }
  | { type: "paragraph"; id: string; text: string }
  | { type: "button"; id: string; text: string; url: string; color?: string }
  | { type: "divider"; id: string }
  | { type: "image"; id: string; src: string; alt: string; width?: number }
  | { type: "spacer"; id: string; height: number }

/* ─── Entities (derived from OpenAPI) ─── */

type EmailTemplateWire = Schemas["EmailTemplateResponseDto"]

/** GET/POST/PATCH `/dashboard/comms/email-templates`: the persisted row. */
export type EmailTemplate = Omit<EmailTemplateWire, "blocks"> & {
  blocks: EmailBlock[] | null
}

/** GET list envelope (the route paginates; the dashboard reads `items`). */
export type PaginatedEmailTemplates = Schemas["PaginatedEmailTemplatesResponseDto"]

/** One page of the list, with the narrowed block vocabulary. */
export type EmailTemplateListPage = Omit<PaginatedEmailTemplates, "items"> & {
  items: EmailTemplate[]
}

/* ─── Request payloads (derived; `blocks` restored to the builder union) ─── */

type UpdateEmailTemplateBody = Schemas["UpdateEmailTemplateDto"]

/** PATCH body. The documented `blocks` items are an opaque object, so the
 *  builder union replaces them; every other field is the wire contract. */
export type UpdateEmailTemplatePayload = Omit<UpdateEmailTemplateBody, "blocks"> & {
  blocks?: EmailBlock[]
}

/** The preview body's documented `context` is an open object; keep it as such. */
export interface TemplatePreviewPayload {
  context: Record<string, unknown>
}

/** POST `/dashboard/comms/email-templates/:id/preview` result. */
export type TemplatePreviewResult = Schemas["EmailTemplatePreviewResponseDto"]
